-- Repeatable seed for the Qudsayya pilot's LAUNCH CONTENT (the Task-31
-- diagnosis: a data-empty backend cannot show its power — this file is the
-- content owner's decision, executed on the 2026-09-30 order «قم بملئ محتوى
-- كامل لكل المنصة»).
--
-- Contract (the R__seed_geo_qudsaya discipline):
--   * Fixed UUIDs per table in closed, reserved ranges (33..43 prefixes);
--     organic rows can never collide. R__ re-applies on checksum change and
--     converges the seed's own rows by FIXED id (ON CONFLICT (id) DO UPDATE
--     for reference-shaped rows; DO NOTHING for event-shaped rows, which
--     never drift). Admin/user-created rows are never touched.
--   * The category vocabulary stays CLOSED to the code-documented 'stay'
--     (V70's declared product gate — no vocabulary is invented here).
--   * Geo references stay inside the geo seed's closed 6-row skeleton.
--   * Past timestamps are literals (the seed's history is stable); future
--     windows (listing expiry, boosts, availability, upcoming stays, view
--     days) are now()/CURRENT_DATE-relative so a future full rebuild (the
--     quota-cycle reality) regenerates them fresh.
--   * Photos: media rows point at objects ALREADY in the S3 bucket
--     (listings/<listingId>/<mediaId>.jpg + /thumb) — the bucket outlives
--     database rebuilds, so re-seeding re-links working presigned photos.
--   * Direct SQL bypasses Envers by nature (the documented geo D-E11
--     precedent: the _aud mirrors record the first real app write).
--   * NO credentials: login rows (auth_users) are bootstrapped out-of-band
--     (scripts/apply_seed.py, bcrypt with its DelegatingPasswordEncoder
--     id-prefix) — the N1 rule that retired the old admin seed.
--
-- Generated by scripts/emit_seed_sql.py from scripts/seed_dataset.py
-- (single source of truth; emit day 2026-09-29).
--
-- ENVIRONMENT GATE (prod/dev vs test): the whole body is wrapped in ONE
-- placeholder-gated DO block. ${seedContent} binds "true" by default
-- (application.yml — prod, dev and the migrator inherit it) and "false"
-- ONLY in the test profile (application-test.yml): the Qudsayya pilot
-- content is production data for the trial zone, not a test fixture, and
-- the flyway-enabled integration tests keep their pristine-database
-- contracts (absolute counts, page-0 composition, full-table cleanups)
-- exactly as they were before this seed existed. Flyway still records
-- the migration in EVERY environment (the DO block runs as a no-op
-- where gated) — the history stays consistent everywhere. An unresolved
-- placeholder (raw psql) also evaluates false: fail-safe no-op.

-- ---------------------------------------------------------------------------
-- The platform's people: 6 provider personas + 5 consumer personas.
DO $seed$
BEGIN
    IF '${seedContent}' = 'true' THEN
ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, email = EXCLUDED.email,
    display_name = EXCLUDED.display_name, role = EXCLUDED.role, is_deleted = FALSE;

-- Provider profiles: 5 VERIFIED (public pages + listings) + 1 PENDING (freshly
-- registered, honestly empty). rating_average = the exact mean of each
-- provider's forward reviews below (the L21 aggregate, precomputed).
ON CONFLICT (id) DO UPDATE SET display_name = EXCLUDED.display_name, bio = EXCLUDED.bio,
    status = EXCLUDED.status, user_id = EXCLUDED.user_id, is_deleted = FALSE,
    rating_average = EXCLUDED.rating_average, actor_type = EXCLUDED.actor_type,
    agency_name = EXCLUDED.agency_name, license_number = EXCLUDED.license_number;

-- 24 listings: 18 RENT stays + 2 commercial RENT + 4 SALE across the three
-- Qudsayya neighborhoods; 21 ACTIVE (75-day expiry, 3 boosted windows),
-- 2 DRAFT, 1 PAUSED(MANUAL) — a realistic pipeline, not a flat demo wall.
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
    price_cents = EXCLUDED.price_cents, status = EXCLUDED.status, is_deleted = FALSE,
    max_guests = EXCLUDED.max_guests, expires_at = EXCLUDED.expires_at,
    promoted_until = EXCLUDED.promoted_until, paused_reason = EXCLUDED.paused_reason;

-- The real-estate vertical block for every listing (V48): Qudsayya-area
-- coordinates, Arabic amenity vocabulary (free-form strings, the frontend's
-- own contract), RENT/SALE and the six property types.
ON CONFLICT (id) DO UPDATE SET purpose = EXCLUDED.purpose, property_type = EXCLUDED.property_type,
    area_m2 = EXCLUDED.area_m2, rooms = EXCLUDED.rooms, bathrooms = EXCLUDED.bathrooms,
    floor_number = EXCLUDED.floor_number, total_floors = EXCLUDED.total_floors,
    building_year = EXCLUDED.building_year, furnished = EXCLUDED.furnished,
    amenities = EXCLUDED.amenities, available_from = EXCLUDED.available_from,
    location_id = EXCLUDED.location_id, latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude, is_deleted = FALSE;

-- Dynamic pricing (V41): weekend multipliers on 10 stay listings.
ON CONFLICT (id) DO UPDATE SET multiplier = EXCLUDED.multiplier, is_deleted = FALSE;
-- Seasonal absolute rates (non-overlapping per listing — the EXCLUDE
-- constraint's own contract): autumn/winter/holiday/summer windows.
ON CONFLICT (id) DO UPDATE SET from_date = EXCLUDED.from_date, to_date = EXCLUDED.to_date,
    price_cents = EXCLUDED.price_cents, is_deleted = FALSE;

-- 16 bookings: 11 past COMPLETED (the review fuel), 3 upcoming CONFIRMED,
-- 1 CANCELLED, 1 PENDING — the booking lifecycle in every real state.
ON CONFLICT (id) DO NOTHING;

-- 11 forward reviews (4 with provider replies) + 6 reverse reviews
-- (providers rating consumers, V45) — the two-way review fabric.
ON CONFLICT (id) DO UPDATE SET rating = EXCLUDED.rating, comment = EXCLUDED.comment,
    is_deleted = FALSE, reply = EXCLUDED.reply, replied_at = EXCLUDED.replied_at,
    direction = EXCLUDED.direction, reviewee_id = EXCLUDED.reviewee_id;

-- One ACTIVE home-neighborhood membership per person (the V60 partial
-- unique's own shape): the community layer's scope anchor.
ON CONFLICT (id) DO NOTHING;

-- 13 neighborhood posts across the three hoods, in the three published
-- categories; every author posts in their OWN membership neighborhood.
ON CONFLICT (id) DO UPDATE SET category = EXCLUDED.category, title = EXCLUDED.title,
    body = EXCLUDED.body, status = 'VISIBLE', is_deleted = FALSE, location_id = EXCLUDED.location_id;

ON CONFLICT (id) DO NOTHING;

-- 4 conversations (1 booking-anchored + 3 direct, canonical pair order) with
-- 12 messages — the inbox fabric for both demo roles.
ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;

-- 5 inbox leads on the commercial/sale listings (the V34 lead channel).
ON CONFLICT (id) DO NOTHING;

-- 57 photo assets, each pointing at the JPEG + /thumb pair already in the S3
-- bucket marketplace-dayf — presigned reads work immediately after any
-- database rebuild because the bucket outlives the database.
ON CONFLICT (id) DO UPDATE SET status = 'UPLOADED', is_deleted = FALSE,
    position = EXCLUDED.position, size_bytes = EXCLUDED.size_bytes,
    thumb_object_key = EXCLUDED.thumb_object_key;

-- 72 upcoming availability windows for the four stay providers (future
-- windows as literals for the CURRENT cycle; a later rebuild regenerates
-- them fresh with this file's checksum change — the slot set is advisory
-- capacity, not booked inventory).
ON CONFLICT (id) DO NOTHING;

-- 294 daily-view aggregates over the last 14 days for the 21 ACTIVE listings
-- (deterministic counts; view_date rides CURRENT_DATE so a rebuild reshapes
-- the same window around its own today) — the analytics surfaces' fuel.
ON CONFLICT (id) DO NOTHING;

    END IF;
END
$seed$;
