    ('34343434-3434-4343-8343-343434340001', 'محمد الحموي', 'أعمل في مجال تأجير الشقق المفروشة في قدسيا البلد منذ عام 2015. أقدم شققاً نظيفة وأسعاراً مناسبة للعائلات والطلاب، والرد على الاستفسارات خلال ساعات.', 'VERIFIED', '2026-03-03 21:00:46+00', '2026-03-03 21:00:46+00', 0, '33333333-3333-4333-8333-333333330001', FALSE, 'seed', 'seed', 4.33, 'INDIVIDUAL', NULL, NULL),
    ('34343434-3434-4343-8343-343434340002', 'سميرة العلي', 'وسيطة عقارية مستقلة في ضاحية قدسيا، أساعدكم في اختيار الشقة المناسبة بميزانية مناسبة. خبرة سبع سنوات في سوق قدسيا وريف دمشق.', 'VERIFIED', '2026-04-02 21:00:46+00', '2026-04-02 21:00:46+00', 0, '33333333-3333-4333-8333-333333330002', FALSE, 'seed', 'seed', 4.0, 'INDEPENDENT_BROKER', NULL, 'وس-771/2025'),
    ('34343434-3434-4343-8343-343434340003', 'مكتب قدسيا للعقارات', 'مكتب عقاري مرخص في منطقة الهامة، نخدم قدسيا وريف دمشق منذ 2018. تخصصنا الشقق المفروشة والفلل العائلية ونظمنا إقامات العائلات والمناسبات الصغيرة.', 'VERIFIED', '2025-08-25 21:00:46+00', '2025-08-25 21:00:46+00', 0, '33333333-3333-4333-8333-333333330003', FALSE, 'seed', 'seed', 4.5, 'AGENCY', 'مكتب قدسيا للعقارات', 'بر-3341/2024'),
    ('34343434-3434-4343-8343-343434340004', 'رامي خوري', 'مالك شقق تراثية ومفروشة في قلب قدسيا البلد. الشقق مجهزة بالكامل وجاهزة للسكن الفوري، وأحرص على صيانتها بشكل دوري.', 'VERIFIED', '2026-05-02 21:00:46+00', '2026-05-02 21:00:46+00', 0, '33333333-3333-4333-8333-333333330004', FALSE, 'seed', 'seed', 5.0, 'INDIVIDUAL', NULL, NULL),
    ('34343434-3434-4343-8343-343434340005', 'شركة الوفاء العقارية', 'شركة عقارية متخصصة في بيع وإيجار العقارات السكنية والتجارية في قدسيا والمناطق المجاورة. لدينا محفظة متنوعة من الشقق والمحال والمكاتب والأراضي.', 'VERIFIED', '2025-04-27 21:00:46+00', '2025-04-27 21:00:46+00', 0, '33333333-3333-4333-8333-333333330005', FALSE, 'seed', 'seed', NULL, 'AGENCY', 'شركة الوفاء العقارية', 'بر-1198/2023'),
    ('34343434-3434-4343-8343-343434340006', 'ليلى حداد', 'وسيطة عقارية حديثة الترخيص، أبحث عن أفضل الفرص السكنية في ضاحية قدسيا. سيتم تفعيل ملفي قريباً بعد إتمام التحقق.', 'PENDING', '2026-09-26 21:00:46+00', '2026-09-26 21:00:46+00', 0, '33333333-3333-4333-8333-333333330006', FALSE, 'seed', 'seed', NULL, 'INDEPENDENT_BROKER', NULL, 'وس-995/2026')
