    ('36363636-3636-4363-8363-363636360001', '33333333-3333-4333-8333-333333330001', 'شقة مفروشة فاخرة ٣ غرف — قدسيا البلد', 'شقة مفروشة بالكامل في قلب قدسيا البلد، على بعد دقائق من الساحة والخدمات جميعها. صالة واسعة وثلاث غرف نوم مكيّفة، والمطبخ مجهز بكل الأدوات. مناسبة للعائلات، والسعر يشمل الماء والصيانة. الحجز الليلي، وخصم للإقامات الطويلة.', 'stay', 24000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-06 21:00:46+00', 'seed', '2026-07-07 21:00:46+00', 6, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360002', '33333333-3333-4333-8333-333333330001', 'شقة عائلية غرفتين — قرب ساحة البلد', 'شقة عائلية هادئة قرب ساحة قدسيا، غرفتان واسعتان وصالة مريحة وإطلالة على الشارع الرئيسي. قريبة من المدارس والمخابز والمواصلات. فرش جديد، والاستلام يومي من الساعة الثانية ظهراً.', 'stay', 21000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-11 21:00:46+00', 'seed', '2026-07-12 21:00:46+00', 4, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360003', '33333333-3333-4333-8333-333333330001', 'استوديو مفروش للطلاب — قدسيا البلد', 'استوديو مناسب للطلاب أو الأزواج، مساحة ذكية ومرتبة، سرير مزدوج ومطبخ صغير مجهز. الموقع ممتاز قرب المعاهد وخطوط المواصلات. أسعار خاصة للطلاب على الحجز الشهري.', 'stay', 13000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-21 21:00:46+00', 'seed', '2026-07-22 21:00:46+00', 2, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360004', '33333333-3333-4333-8333-333333330001', 'شقة مفروشة ببلكونة مطلة — الطابق الأخير', 'شقة في الطابق الأخير ببلكونة واسعة مطلة على المدينة والجبال، الإطلالة عند الغروب لا تُفوّت. غرفتان مع حمامين، هادئة ومرتبة. مثالية للأزواج والعائلات الصغيرة.', 'stay', 26000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-31 21:00:46+00', 'seed', '2026-08-01 21:00:46+00', 4, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360005', '33333333-3333-4333-8333-333333330001', 'غرفة خاصة بشقة مشتركة — للطلاب', 'غرفة خاصة داخل شقة مشتركة، مناسبة لطالب أو موظف. تشارك الصالة والمطبخ والحمام مع مستأجر آخر هادئ. السعر شهري شامل الفواتير — بانتظار استكمال التفاصيل قبل النشر.', 'stay', 8000, 'SAR', 'DRAFT', FALSE, 0, 'seed', '2026-09-24 21:00:46+00', 'seed', '2026-09-25 21:00:46+00', 1, NULL, NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360006', '33333333-3333-4333-8333-333333330002', 'شقة حديثة غرفتين — ضاحية قدسيا', 'شقة حديثة البناء في ضاحية قدسيا، تشطيب جديد وفرش أنيق. الحي هادئ وقريب من الحدائق والمدارس الخاصة. الوسيطة سميرة تتولى التسليم والاستلام وتضمن مطابقة الشقة للوصف.', 'stay', 19000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-16 21:00:46+00', 'seed', '2026-07-17 21:00:46+00', 4, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360007', '33333333-3333-4333-8333-333333330002', 'شقة مفروشة ٣ غرف — ضاحية قدسيا الحديثة', 'شقة واسعة في أحدث مباني ضاحية قدسيا، ثلاث غرف نوم مكيّفة وصالة عائلية كبيرة. البناية فيها منطقة أطفال ومواقف خاصة. مناسبة لعائلتين متجاورتين أو العائلات الكبيرة.', 'stay', 29000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-25 21:00:46+00', 'seed', '2026-07-26 21:00:46+00', 6, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360008', '33333333-3333-4333-8333-333333330002', 'بنتهاوس بتراس خاص — إطلالة جبلية', 'بنتهاوس في أعلى البناية بتراس خاص واسع وإطلالة جبلية ساحرة على جبال القلمون. ثلاث غرف فاخرة وثلاثة حمامات، تشطيب درجة أولى. تجربة فريدة للإقامات المميزة والمناسبات الصغيرة.', 'stay', 38000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-08-05 21:00:46+00', 'seed', '2026-08-06 21:00:46+00', 6, now() + interval '75 days', NULL, NULL, now() + interval '14 days'),
    ('36363636-3636-4363-8363-363636360009', '33333333-3333-4333-8333-333333330002', 'شقة اقتصادية — ضاحية قدسيا', 'شقة اقتصادية للميزانيات المحدودة، غرفة وصالة ومطبخ مجهز. الخيار الأفضل للإقامات القصيرة العملية — بانتظار استكمال الصور قبل النشر.', 'stay', 12000, 'SAR', 'DRAFT', FALSE, 0, 'seed', '2026-09-25 21:00:46+00', 'seed', '2026-09-26 21:00:46+00', 2, NULL, NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360010', '33333333-3333-4333-8333-333333330003', 'فيلا مفروشة ٥ غرف مع حديقة — الهامة', 'فيلا عائلية فاخرة في الهامة مع حديقة خاصة ومدخل مستقل. خمس غرف نوم وأربع حمامات وصالتان، مثالية للعائلات الكبيرة والمناسبات الصغيرة. المكتب يقدم خدمة تنظيم الإقامة كاملة مع إمكانية ترتيب الطعام.', 'stay', 65000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-01 21:00:46+00', 'seed', '2026-07-02 21:00:46+00', 10, now() + interval '75 days', NULL, NULL, now() + interval '14 days'),
    ('36363636-3636-4363-8363-363636360011', '33333333-3333-4333-8333-333333330003', 'شقة غرفتين — الهامة قرب الخدمات', 'شقة عملية قرب خدمات الهامة كافة: مدارس، أسواق، مواصلات. غرفتان وصالة وحمام، فرش نظيف وصيانة دورية. خيار ممتاز للإقامات المتوسطة بأسعار معقولة.', 'stay', 16000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-19 21:00:46+00', 'seed', '2026-07-20 21:00:46+00', 4, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360012', '33333333-3333-4333-8333-333333330003', 'شقة مفروشة ٣ غرف — الهامة الجديدة', 'شقة مفروشة عصرية في أبنية الهامة الجديدة، ثلاث غرف مكيّفة وصالة مشرقة ببلكونة. قريبة من الطريق الرئيسي مع هدوء داخلي. الأسعار مرنة للإقامات الأسبوعية والشهرية.', 'stay', 25000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-27 21:00:46+00', 'seed', '2026-07-28 21:00:46+00', 6, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360013', '33333333-3333-4333-8333-333333330003', 'شاليه خشبي مع مدفأة — الهامة', 'شاليه خشبي دافئ بمدفأة تقليدية وتراس بإطلالة جبلية، جو رومانسي مثالي لفصل الشتاء. غرفتان ومطبخ مجهز. الشاليه موقوف مؤقتاً لأعمال صيانة وسيعود قبل موسم الشتاء.', 'stay', 30000, 'SAR', 'PAUSED', FALSE, 0, 'seed', '2026-08-12 21:00:46+00', 'seed', '2026-08-13 21:00:46+00', 4, NULL, 'MANUAL', NULL, NULL),
    ('36363636-3636-4363-8363-363636360014', '33333333-3333-4333-8333-333333330003', 'شقة واسعة عائلية ٤ غرف — الهامة', 'شقة واسعة مصممة للعائلات الكبيرة: أربع غرف نوم وصالة كبيرة ومطبخ راح. الطابق الأول مع مدخل سهل ومناسب لكبار السن. سكن دائم أو إقامات طويلة باتفاق خاص.', 'stay', 33000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-08-18 21:00:46+00', 'seed', '2026-08-19 21:00:46+00', 8, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360015', '33333333-3333-4333-8333-333333330003', 'استوديو ديلوكس — الهامة', 'استوديو ديلوكس بتجهيز كامل: سرير مريح، خزانة، مطبخ أنيق وحمام حديث. مناسب لرحلات العمل والإقامات الفردية الهادئة في موقع مركزي داخل الهامة.', 'stay', 14000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-08-24 21:00:46+00', 'seed', '2026-08-25 21:00:46+00', 2, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360016', '33333333-3333-4333-8333-333333330004', 'شقة تراثية دمشقية مفروشة — قدسيا البلد', 'تجربة سكن فريدة في شقة تراثية دمشقية الأصل: سقف مرسوم يدوياً وأثاث مُرصّع بالصدف ونقوش عربية ساحرة. البناء من السبعينات ومُرمم بعناية يحافظ على روح البيت الشامي مع وسائل الراحة الحديثة.', 'stay', 23000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-08-02 21:00:46+00', 'seed', '2026-08-03 21:00:46+00', 4, now() + interval '75 days', NULL, NULL, now() + interval '14 days'),
    ('36363636-3636-4363-8363-363636360017', '33333333-3333-4333-8333-333333330004', 'شقة غرفة وصالة — قرب المشفى', 'شقة عملية قرب المشفى والمنطقة الطبية، الخيار الأمثل لمرافقي المرضى ورحلات العلاج. غرفة وصالة وحمام، نظيفة وهادئة، وبالقرب من الصيدليات والمخابز.', 'stay', 11000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-08-28 21:00:46+00', 'seed', '2026-08-29 21:00:46+00', 2, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360018', '33333333-3333-4333-8333-333333330004', 'شقة مفروشة جديدة الفرش — قدسيا البلد', 'شقة مفروشة بفرش جديد كلياً: أسرّة جديدة وأدوات مطبخ غير مستخدمة. غرفتان وحمامان في موقع مركزي بقدسيا البلد. جاهزة للاستلام الفوري دون أي التزامات إضافية.', 'stay', 22000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-09-01 21:00:46+00', 'seed', '2026-09-02 21:00:46+00', 4, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360019', '33333333-3333-4333-8333-333333330005', 'مكتب تجاري مجهز ٦٠م — الشارع الرئيسي', 'مكتب تجاري جاهز للعمل على الشارع الرئيسي في قدسيا: قاعتان بفاصل زجاجي، تمديدات شبكة وكهرباء صناعية جاهزة، وتكييف مركزي. موقع حيوي يطل على حركة الشارع — مناسب للشركات والخدمات المهنية. الإيجار شهري.', 'stay', 350000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-06-26 21:00:46+00', 'seed', '2026-06-27 21:00:46+00', NULL, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360020', '33333333-3333-4333-8333-333333330005', 'محل تجاري ٤٥م بواجهة زجاجية — سوق قدسيا', 'محل تجاري بواجهة زجاجية حديثة داخل سوق قدسيا النشط، حركة مشاة يومية عالية. مساحة مفتوحة ٤٥م مع مخزن صغير وحمام. جاهز لأي نشاط تجاري — الإيجار شهري والعقد سنوي قابل للتجديد.', 'stay', 280000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-07-03 21:00:46+00', 'seed', '2026-07-04 21:00:46+00', NULL, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360021', '33333333-3333-4333-8333-333333330005', 'شقة للبيع ١٤٠م — ضاحية قدسيا الجديدة', 'شقة جديدة للبيع في أرقى أحياء ضاحية قدسيا: ١٤٠م ثلاث غرف وصالتين، تشطيب سوبر لوكس والبناية جديدة ٢٠٢١. طابق ثالث بإطلالة مفتوحة، الطابو أخضر جاهز للفراغ الفوري. السعر قابل للتداول الجدي.', 'stay', 21000000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-06-01 21:00:46+00', 'seed', '2026-06-02 21:00:46+00', NULL, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360022', '33333333-3333-4333-8333-333333330005', 'شقة للبيع ٩٥م — قدسيا البلد', 'شقة للبيع في قلب قدسيا البلد: ٩٥م غرفتان وصالة وحمام، بناية نظيفة ومدخل محترم. الموقع لا يُعوّض — قرب الساحة والخدمات والمواصلات. مناسبة للسكن أو الاستثمار بالإيجار.', 'stay', 14500000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-06-11 21:00:46+00', 'seed', '2026-06-12 21:00:46+00', NULL, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360023', '33333333-3333-4333-8333-333333330005', 'فيلا للبيع ٣٥٠م مع حديقة — الهامة', 'فيلا مستقلة للبيع في أرقى منطقة بالهامة: ٣٥٠م بناء على طابقين مع حديقة ٢٠٠م وبئر ماء خاص. تشطيب فاخر وتوزيع ممتاز للعائلة الكبيرة. جاهزة للسكن الفوري، والمعاينة بموعد مسبق.', 'stay', 52000000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-06-16 21:00:46+00', 'seed', '2026-06-17 21:00:46+00', NULL, now() + interval '75 days', NULL, NULL, NULL),
    ('36363636-3636-4363-8363-363636360024', '33333333-3333-4333-8333-333333330005', 'أرض للبيع ٦٠٠م — مشارع الهامة', 'أرض للبيع في مشارع الهامة بمساحة ٦٠٠م، حدود واضحة وشارع معبّد حتى الأرض. مناسبة لبناء فيلا أو مشروع استثماري صغير. السعر سلّمي والجدي فقط — الوثائق كاملة وجاهزة لدى المكتب.', 'stay', 9000000, 'SAR', 'ACTIVE', FALSE, 0, 'seed', '2026-06-23 21:00:46+00', 'seed', '2026-06-24 21:00:46+00', NULL, now() + interval '75 days', NULL, NULL, NULL)
