INSERT INTO reviews (id, booking_id, reviewer_id, provider_id, rating, comment, is_deleted, version, created_by, created_at, updated_by, updated_at, reply, replied_at, direction, reviewee_id) VALUES
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0001', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0001', '35353535-3535-4535-8353-353535350001', '33333333-3333-4333-8333-333333330001', 5, 'شقة نظيفة وأنيقة والموقع ممتاز قرب كل الخدمات. صاحب الشقة متعاون جداً ورد بسرعة على كل الاستفسارات. أنصح بها للعائلات.', FALSE, 0, 'seed', '2026-08-16 21:00:46+00', 'seed', '2026-08-16 21:00:46+00', NULL, NULL, 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0002', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0002', '35353535-3535-4535-8353-353535350002', '33333333-3333-4333-8333-333333330001', 4, 'إقامة مريحة والشقة مطابقة للصور تماماً. السعر مناسب مقابل الموقع.', FALSE, 0, 'seed', '2026-08-21 21:00:46+00', 'seed', '2026-08-21 21:00:46+00', 'شكراً لثقتكم، ننتظر زيارتكم القادمة دائماً.', '2026-08-22 21:00:46+00', 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0003', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0003', '35353535-3535-4535-8353-353535350003', '33333333-3333-4333-8333-333333330002', 5, 'الشقة حديثة والحي هادئ جداً. الوسيطة سميرة تعاملت معنا باحترافية عالية من الحجز حتى التسليم.', FALSE, 0, 'seed', '2026-08-23 21:00:46+00', 'seed', '2026-08-23 21:00:46+00', NULL, NULL, 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0004', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0004', '35353535-3535-4535-8353-353535350001', '33333333-3333-4333-8333-333333330002', 4, 'إطلالة البنتهاوس رائعة فعلاً وتستحق السعر. التراس واسع وجلسات المساء كانت مميزة.', FALSE, 0, 'seed', '2026-08-26 21:00:46+00', 'seed', '2026-08-26 21:00:46+00', 'سعدنا بخدمتكم! الباب مفتوح دائماً.', '2026-08-27 21:00:46+00', 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0005', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0005', '35353535-3535-4535-8353-353535350004', '33333333-3333-4333-8333-333333330003', 4, 'شقة جيدة وقريبة من كل الخدمات. المكتب متعاون وإنهاء الإجراءات كان سريعاً ونظيفاً.', FALSE, 0, 'seed', '2026-08-31 21:00:46+00', 'seed', '2026-08-31 21:00:46+00', NULL, NULL, 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0006', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0006', '35353535-3535-4535-8353-353535350005', '33333333-3333-4333-8333-333333330003', 5, 'شقة رائعة للعائلة، الأطفال استمتعوا كثيراً والفرش نظيف ومريح. تجربة ممتازة من الحجز حتى المغادرة.', FALSE, 0, 'seed', '2026-09-02 21:00:46+00', 'seed', '2026-09-02 21:00:46+00', NULL, NULL, 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0007', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0007', '35353535-3535-4535-8353-353535350002', '33333333-3333-4333-8333-333333330004', 5, 'الشقة التراثية تجربة فريدة فعلاً، النقوش والأثاث الدمشقي ساحر. نظيفة ومرتبة والجلسة التراثية لا تُنسى.', FALSE, 0, 'seed', '2026-09-05 21:00:46+00', 'seed', '2026-09-05 21:00:46+00', NULL, NULL, 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0008', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0008', '35353535-3535-4535-8353-353535350003', '33333333-3333-4333-8333-333333330002', 3, 'الشقة جيدة بشكل عام لكن تكييف غرفة النوم الرئيسية كان ضعيفاً في الحر. الباقي ممتاز والتواصل سريع.', FALSE, 0, 'seed', '2026-09-08 21:00:46+00', 'seed', '2026-09-08 21:00:46+00', 'شكراً للملاحظة، تم فحص التكييف واستبداله بمكينة أقوى هذا الأسبوع.', '2026-09-09 21:00:46+00', 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0009', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0009', '35353535-3535-4535-8353-353535350004', '33333333-3333-4333-8333-333333330001', 4, 'بلكونة الطابق الأخير إطلالتها مذهلة عند الغروب. الشقة نظيفة ومجهزة والاستلام كان منظماً.', FALSE, 0, 'seed', '2026-09-12 21:00:46+00', 'seed', '2026-09-12 21:00:46+00', NULL, NULL, 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0010', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0010', '35353535-3535-4535-8353-353535350005', '33333333-3333-4333-8333-333333330003', 5, 'الفيلا تستحق كل ريال. الحديقة كبيرة والتجهيزات كاملة، وعرسنا العائلي الصغير كان مثالياً. خدمة المكتب راقية من الألف إلى الياء.', FALSE, 0, 'seed', '2026-09-15 21:00:46+00', 'seed', '2026-09-15 21:00:46+00', 'يسعدنا أن كانت مناسبتكم مميزة! ننتظر عودتكم.', '2026-09-16 21:00:46+00', 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0011', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0011', '35353535-3535-4535-8353-353535350001', '33333333-3333-4333-8333-333333330003', 4, 'شقة واسعة تناسب العائلات الكبيرة فعلاً. الأسرّ مريحة والحمامات نظيفة، والطابق الأول مريح لكبار السن.', FALSE, 0, 'seed', '2026-09-18 21:00:46+00', 'seed', '2026-09-18 21:00:46+00', NULL, NULL, 'CONSUMER_TO_PROVIDER', NULL),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0012', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0001', '33333333-3333-4333-8333-333333330001', '33333333-3333-4333-8333-333333330001', 5, 'ضيف محترم وهادئ، سلم الشقة كما استلمها تماماً. نتمنى رؤيته مجدداً.', FALSE, 0, 'seed', '2026-08-17 21:00:46+00', 'seed', '2026-08-17 21:00:46+00', NULL, NULL, 'PROVIDER_TO_CONSUMER', '35353535-3535-4535-8353-353535350001'),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0013', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0003', '33333333-3333-4333-8333-333333330002', '33333333-3333-4333-8333-333333330002', 5, 'عائلة لطيفة ومتعاونة، التزام تام بمواعيد الاستلام والتسليم.', FALSE, 0, 'seed', '2026-08-24 21:00:46+00', 'seed', '2026-08-24 21:00:46+00', NULL, NULL, 'PROVIDER_TO_CONSUMER', '35353535-3535-4535-8353-353535350003'),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0014', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0006', '33333333-3333-4333-8333-333333330003', '33333333-3333-4333-8333-333333330003', 5, 'ضيوف مميزون، احترموا الشقة وغادروا في الموعد تماماً.', FALSE, 0, 'seed', '2026-09-03 21:00:46+00', 'seed', '2026-09-03 21:00:46+00', NULL, NULL, 'PROVIDER_TO_CONSUMER', '35353535-3535-4535-8353-353535350005'),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0015', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0008', '33333333-3333-4333-8333-333333330002', '33333333-3333-4333-8333-333333330002', 4, 'ضيف جيد وتواصل واضح ومباشر. ملاحظاته كانت مهذبة ومفيدة.', FALSE, 0, 'seed', '2026-09-09 21:00:46+00', 'seed', '2026-09-09 21:00:46+00', NULL, NULL, 'PROVIDER_TO_CONSUMER', '35353535-3535-4535-8353-353535350003'),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0016', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0010', '33333333-3333-4333-8333-333333330003', '33333333-3333-4333-8333-333333330003', 5, 'منظمون ومحترمون جداً في المناسبات. سهل التعامل معهم بكل تأكيد.', FALSE, 0, 'seed', '2026-09-16 21:00:46+00', 'seed', '2026-09-16 21:00:46+00', NULL, NULL, 'PROVIDER_TO_CONSUMER', '35353535-3535-4535-8353-353535350005'),
    ('3c3c3c3c-3c3c-43c3-83c3-3c3c3c3c0017', '3b3b3b3b-3b3b-43b3-83b3-3b3b3b3b0011', '33333333-3333-4333-8333-333333330003', '33333333-3333-4333-8333-333333330003', 5, 'ضيف نظامي ومهذب، أنصح جميع المزودين بقبول حجوزاته.', FALSE, 0, 'seed', '2026-09-19 21:00:46+00', 'seed', '2026-09-19 21:00:46+00', NULL, NULL, 'PROVIDER_TO_CONSUMER', '35353535-3535-4535-8353-353535350001')
