INSERT INTO neighborhood_posts (id, author_id, location_id, category, title, body, status, is_deleted, version, created_by, created_at, updated_by, updated_at) VALUES
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0001', '35353535-3535-4535-8353-353535350001', '11111111-1111-4111-8111-111111111104', 'GENERAL', 'أنصح بمخبز أبو خالد قرب الساحة', 'جربت مخبز أبو خالد قرب ساحة البلد من أسبوع والمناقيش طرية والفرن نظيف. أسعاره معقولة مقارنة بغيره ويفتح من الفجر. أنصح فيه أهل الحي.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-23 20:00:46+00', 'seed', '2026-09-23 20:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0002', '35353535-3535-4535-8353-353535350004', '11111111-1111-4111-8111-111111111104', 'CLASSIFIED', 'للبيع: دراجة هوائية بحالة ممتازة', 'دراجة هوائية بحالة ممتازة قليلة الاستخدام، فرامل وعدسات جدّدت جديد. السعر ١٥٠ ألف ل.س قابل للتداول قليلاً. التواصل بعد الخامسة مساءً.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-24 19:00:46+00', 'seed', '2026-09-24 19:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0003', '33333333-3333-4333-8333-333333330001', '11111111-1111-4111-8111-111111111104', 'CLASSIFIED', 'متوفر شقق مفروشة للإيجار الليلي في البلد', 'لمن يبحث عن إقامة قصيرة في قدسيا البلد: متوفر لدي شقق مفروشة غرفتين وثلاث غرف بأسعار من ١٣٠ إلى ٢٦٠ ريال. جميعها قرب الخدمات — التفاصيل في ملفي.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-25 18:00:46+00', 'seed', '2026-09-25 18:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0004', '35353535-3535-4535-8353-353535350001', '11111111-1111-4111-8111-111111111104', 'GENERAL', 'هل يوجد مدرسة خاصة قريبة من البلد؟', 'ننتقل للسكن في قدسيا البلد قريباً وبحثت عن مدرسة خاصة لأولادي قريبة. سمعت عن مدرستين لكن أريد تجاربكم الحقيقية، خصوصاً من ناحية المتابعة والنقل.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-26 17:00:46+00', 'seed', '2026-09-26 17:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0005', '33333333-3333-4333-8333-333333330004', '11111111-1111-4111-8111-111111111104', 'LOST_FOUND', 'ضاعت قطة رمادية قرب جامع النور', 'ضاعت قطة رمادية صغيرة قرب جامع النور ظهر أمس، خجولة جداً وتجري إذا اقتربت منها. لها علامة بيضاء في صدرها. من رآها أرجو التواصل — ولها مكافأة.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-27 16:00:46+00', 'seed', '2026-09-27 16:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0006', '35353535-3535-4535-8353-353535350002', '11111111-1111-4111-8111-111111111105', 'GENERAL', 'أفضل صيدليات الضاحية التي تعمل ليلاً؟', 'احتجت صيدلية الساعة ١١ مساءً ولم أجد غير واحدة مفتوحة بعيداً. ما تجاربكم بصيدليات الضاحية الليلية؟ وهل في صف ديوتي منظّم بينها؟', 'VISIBLE', FALSE, 0, 'seed', '2026-09-22 15:00:46+00', 'seed', '2026-09-22 15:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0007', '33333333-3333-4333-8333-333333330002', '11111111-1111-4111-8111-111111111105', 'CLASSIFIED', 'شقة غرفتين للإيجار الشهري في الضاحية', 'للعائلات الصغيرة: شقة غرفتين مفروشة للإيجار الشهري في ضاحية قدسيا، بناية جديدة وموقف سيارات. التواصل معي للاستفسار والمعاينة.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-24 14:00:46+00', 'seed', '2026-09-24 14:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0008', '35353535-3535-4535-8353-353535350002', '11111111-1111-4111-8111-111111111105', 'GENERAL', 'سؤال عن مول الضاحية الجديد', 'سمعت أن مول الضاحية الجديد بدأ يعمل جزئياً. هل فعلاً فيه سوبرماركت كبير ومطاعم؟ وأنتم كيف وجدتوا الأسعار مقارنة بأسواق البلد؟', 'VISIBLE', FALSE, 0, 'seed', '2026-09-26 13:00:46+00', 'seed', '2026-09-26 13:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0009', '33333333-3333-4333-8333-333333330005', '11111111-1111-4111-8111-111111111105', 'CLASSIFIED', 'فرص بيع مميزة وصلت حديثاً لشركة الوفاء', 'وصلتنا شقق للبيع في ضاحية قدسيا الجديدة بأسعار تنافسية وطابو جاهز، ومنها شقة ١٤٠م بسعر مميز لأسبوعين فقط. المعاينات بموعد مسبق.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-27 12:00:46+00', 'seed', '2026-09-27 12:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0010', '35353535-3535-4535-8353-353535350003', '11111111-1111-4111-8111-111111111106', 'GENERAL', 'حالة الطريق الرئيسي بعد آخر عاصفة', 'الطريق الرئيسي في الهامة صار أفضل بكثير بعد آخر عاصفة مطرية، التصليحات أغلقت أغلب الحفر. باقي مقطع قصير قرب المدرسة يحتاج انتباه ليلاً.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-21 11:00:46+00', 'seed', '2026-09-21 11:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0011', '35353535-3535-4535-8353-353535350005', '11111111-1111-4111-8111-111111111106', 'CLASSIFIED', 'مطلوب عامل محل حلويات — خبرة سنة', 'محل حلويات في الهامة يطلب عاملاً بخبرة سنة على الأقل، الدوام مسائي والراتب جيد حسب الخبرة. من يعرف شخصاً مناسباً يراسلني.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-25 10:00:46+00', 'seed', '2026-09-25 10:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0012', '33333333-3333-4333-8333-333333330003', '11111111-1111-4111-8111-111111111106', 'GENERAL', 'افتتاح مقرنا الجديد في الهامة — أهلاً بكم', 'يسر مكتب قدسيا للعقارات إعلان انتقاله إلى مقره الجديد في الهامة قرب التقاطع الرئيسي. الخدمات كما هي: إيجار مفروش، إدارة أملاك، ووساطة البيع. أهلاً بزواركم.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-26 21:00:46+00', 'seed', '2026-09-26 21:00:46+00'),
    ('3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0013', '35353535-3535-4535-8353-353535350003', '11111111-1111-4111-8111-111111111106', 'LOST_FOUND', 'عثرت على محفظة قرب حديقة الهامة', 'وجدت محفظة جلدية بنية قرب حديقة الهامة فيها بطاقات باسم صاحبها. عند صاحبها: صف المحتوى بدقة والتواصل معي لاستلامها من مكان آمن.', 'VISIBLE', FALSE, 0, 'seed', '2026-09-28 20:00:46+00', 'seed', '2026-09-28 20:00:46+00')
INSERT INTO post_comments (id, post_id, author_id, body, is_deleted, version, created_by, created_at, updated_by, updated_at) VALUES
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0001', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0001', '35353535-3535-4535-8353-353535350004', 'جربته الأسبوع الماضي، فعلاً مناقيشه من الأفضل بالبلد.', FALSE, 0, 'seed', '2026-09-24 18:00:46+00', 'seed', '2026-09-24 18:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0002', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0001', '33333333-3333-4333-8333-333333330001', 'أنا زبون دائم عنده من سنين — الفورن نظيف دايماً.', FALSE, 0, 'seed', '2026-09-25 15:00:46+00', 'seed', '2026-09-25 15:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0003', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0004', '35353535-3535-4535-8353-353535350004', 'مدرسة الأمل قريبة وفيها نقل خاص، تجربتنا مع أولادي جيدة.', FALSE, 0, 'seed', '2026-09-27 12:00:46+00', 'seed', '2026-09-27 12:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0004', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0004', '33333333-3333-4333-8333-333333330004', 'من موقعي في البلد، أقرب مدرستين على بعد ٥ دقائق سيراً.', FALSE, 0, 'seed', '2026-09-27 20:00:46+00', 'seed', '2026-09-27 20:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0005', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0005', '35353535-3535-4535-8353-353535350001', 'رأيت قطة تشبه الوصف قرب الباكورة صباحاً، راقبوا هناك.', FALSE, 0, 'seed', '2026-09-28 17:00:46+00', 'seed', '2026-09-28 17:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0006', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0006', '35353535-3535-4535-8353-353535350001', 'صيدلية النور في الضاحية فيها صف ديوتي لليل — تجربتي جيدة.', FALSE, 0, 'seed', '2026-09-23 14:00:46+00', 'seed', '2026-09-23 14:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0007', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0006', '33333333-3333-4333-8333-333333330002', 'نفس ملاحظتك، الثانية أقرب لكن تقفل ١٢ غالباً.', FALSE, 0, 'seed', '2026-09-24 11:00:46+00', 'seed', '2026-09-24 11:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0008', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0007', '35353535-3535-4535-8353-353535350002', 'مررت على الشقة، نظيفة فعلاً والبناية هادئة.', FALSE, 0, 'seed', '2026-09-25 19:00:46+00', 'seed', '2026-09-25 19:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0009', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0008', '33333333-3333-4333-8333-333333330005', 'السوبرماركت فتح فعلاً والأسعار معقولة، المطاعم بعد أسبوعين.', FALSE, 0, 'seed', '2026-09-27 16:00:46+00', 'seed', '2026-09-27 16:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0010', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0010', '33333333-3333-4333-8333-333333330003', 'شكراً على التحديث، زبائننا صاروا أوفر وقتاً بالوصول إلينا.', FALSE, 0, 'seed', '2026-09-22 13:00:46+00', 'seed', '2026-09-22 13:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0011', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0011', '35353535-3535-4535-8353-353535350003', 'أعرف شاب مناسب من الحي، راسلتك خصوصياً.', FALSE, 0, 'seed', '2026-09-26 21:00:46+00', 'seed', '2026-09-26 21:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0012', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0012', '35353535-3535-4535-8353-353535350005', 'مبروك الانتقال، المكتب الجديد فعلاً مرتب وموقفه مريح.', FALSE, 0, 'seed', '2026-09-27 18:00:46+00', 'seed', '2026-09-27 18:00:46+00'),
    ('3f3f3f3f-3f3f-43f3-83f3-3f3f3f3f0013', '3e3e3e3e-3e3e-43e3-83e3-3e3e3e3e0013', '35353535-3535-4535-8353-353535350005', 'خير عمل — إن شاء الله توصل لصاحبها بسرعة.', FALSE, 0, 'seed', '2026-09-28 15:00:46+00', 'seed', '2026-09-28 15:00:46+00')
