INSERT INTO messages (id, conversation_id, sender_id, content, read, is_deleted, version, created_by, created_at, updated_by, updated_at) VALUES
    ('42424242-4242-4424-8424-424242420001', '41414141-4141-4414-8414-414141410001', '35353535-3535-4535-8353-353535350001', 'مساء الخير أبو محمد، حجزت شقتكم لثلاث ليالٍ الشهر الجاي. ممكن سرير إضافي لطفلي؟', true, FALSE, 0, 'seed', '2026-08-14 19:00:46+00', 'seed', '2026-08-14 19:00:46+00'),
    ('42424242-4242-4424-8424-424242420002', '41414141-4141-4414-8414-414141410001', '33333333-3333-4333-8333-333333330001', 'أهلاً أحمد، مرحباً بكم. السرير الإضافي مجاني وسيكون جاهزاً عند وصولكم.', true, FALSE, 0, 'seed', '2026-08-14 17:00:46+00', 'seed', '2026-08-14 17:00:46+00'),
    ('42424242-4242-4424-8424-424242420003', '41414141-4141-4414-8414-414141410001', '35353535-3535-4535-8353-353535350001', 'شكراً جزيلاً، سنتصل عند الوصول. تقديرك للتقييم وصل وشكراً عليه.', true, FALSE, 0, 'seed', '2026-08-17 15:00:46+00', 'seed', '2026-08-17 15:00:46+00'),
    ('42424242-4242-4424-8424-424242420004', '41414141-4141-4414-8414-414141410002', '35353535-3535-4535-8353-353535350002', 'مرحباً، مهتمة بشقة ٣ غرف في الهامة لخمس ليالٍ من ٢٠ أكتوبر. هل هي متاحة؟', true, FALSE, 0, 'seed', '2026-09-20 13:00:46+00', 'seed', '2026-09-20 13:00:46+00'),
    ('42424242-4242-4424-8424-424242420005', '41414141-4141-4414-8414-414141410002', '33333333-3333-4333-8333-333333330003', 'أهلاً نور، متاحة ونؤكدها لكم بعد موافقتكم على السعر. أرسلت التفاصيل والعقد في الرد.', true, FALSE, 0, 'seed', '2026-09-20 21:00:46+00', 'seed', '2026-09-20 21:00:46+00'),
    ('42424242-4242-4424-8424-424242420006', '41414141-4141-4414-8414-414141410002', '35353535-3535-4535-8353-353535350002', 'وصلني كل شيء، سأؤكد خلال اليومين القادمين بعد ترتيب المواصلات.', true, FALSE, 0, 'seed', '2026-09-21 19:00:46+00', 'seed', '2026-09-21 19:00:46+00'),
    ('42424242-4242-4424-8424-424242420007', '41414141-4141-4414-8414-414141410003', '35353535-3535-4535-8353-353535350003', 'مساء الخير سميرة، وصلني عرضك للبنتهاوس — هل الإطلالة جبلية فعلاً كما في الصور؟', true, FALSE, 0, 'seed', '2026-09-23 17:00:46+00', 'seed', '2026-09-23 17:00:46+00'),
    ('42424242-4242-4424-8424-424242420008', '41414141-4141-4414-8414-414141410003', '33333333-3333-4333-8333-333333330002', 'أهلاً خالد، نعم الإطلالة على القلمون كاملة والتراس واسع. الصور حقيقية من آخر ضيوف.', true, FALSE, 0, 'seed', '2026-09-23 15:00:46+00', 'seed', '2026-09-23 15:00:46+00'),
    ('42424242-4242-4424-8424-424242420009', '41414141-4141-4414-8414-414141410003', '35353535-3535-4535-8353-353535350003', 'ممتاز، سأحجزها لنهاية الأسبوع القادم إن بقيت متاحة.', false, FALSE, 0, 'seed', '2026-09-24 13:00:46+00', 'seed', '2026-09-24 13:00:46+00'),
    ('42424242-4242-4424-8424-424242420010', '41414141-4141-4414-8414-414141410004', '35353535-3535-4535-8353-353535350004', 'مرحباً رامي، الشقة التراثية سببت انبهارنا بالصور — هل الجلسة التراثية مسموح تصويرها؟', true, FALSE, 0, 'seed', '2026-09-27 21:00:46+00', 'seed', '2026-09-27 21:00:46+00'),
    ('42424242-4242-4424-8424-424242420011', '41414141-4141-4414-8414-414141410004', '33333333-3333-4333-8333-333333330004', 'أهلاً رنا، بالتأكيد وصوروا براحتكم. فقط نطلب الاعتناء بالأثاث الصدفي لأنه أصلي.', true, FALSE, 0, 'seed', '2026-09-27 19:00:46+00', 'seed', '2026-09-27 19:00:46+00'),
    ('42424242-4242-4424-8424-424242420012', '41414141-4141-4414-8414-414141410004', '35353535-3535-4535-8353-353535350004', 'طبعاً، سنعاملها كأنها بيتنا. نراكم الجمعة!', false, FALSE, 0, 'seed', '2026-09-28 17:00:46+00', 'seed', '2026-09-28 17:00:46+00')
